def format_few_shot_prompt(count=8):
    """Format a selection of reference scripts for the GPT prompt.

    Uses a diverse subset to cover different story types while keeping
    the prompt size manageable.
    """
    # Pick a diverse set across different topics
    indices = [0, 2, 3, 7, 11, 13, 16, 21, 22, 24]  # diverse topics
    selected = [REFERENCE_SCRIPTS[i] for i in indices[:count]]

    lines = []
    for i, s in enumerate(selected, 1):
        lines.append(f"=== APPROVED SCRIPT {i}: {s['title']} ===")
        lines.append(f"HOOK: {s['hook']}")
        lines.append(f"TEXT: {s['text']}")
        lines.append(f"BODY: {s['body']}")
        lines.append(f"OUTRO: {s['outro']}")
        lines.append("")

    return "\n".join(lines)
